   782  void _faceIjkToVerts(FaceIJK *fijk, int *res, FaceIJK *fijkVerts) {
   783      // the vertexes of an origin-centered cell in a Class II resolution on a
   784      // substrate grid with aperture sequence 33r. The aperture 3 gets us the
   785      // vertices, and the 3r gets us back to Class II.
   786      // vertices listed ccw from the i-axes
   787      CoordIJK vertsCII[NUM_HEX_VERTS] = {
   788          {2, 1, 0},  // 0
   789          {1, 2, 0},  // 1
   790          {0, 2, 1},  // 2
   791          {0, 1, 2},  // 3
   792          {1, 0, 2},  // 4
   793          {2, 0, 1}   // 5
   794      };
   795
   796      // the vertexes of an origin-centered cell in a Class III resolution on a
   797      // substrate grid with aperture sequence 33r7r. The aperture 3 gets us the
   798      // vertices, and the 3r7r gets us to Class II.
   799      // vertices listed ccw from the i-axes
   800      CoordIJK vertsCIII[NUM_HEX_VERTS] = {
   801          {5, 4, 0},  // 0
   802          {1, 5, 0},  // 1
   803          {0, 5, 4},  // 2
   804          {0, 1, 5},  // 3
   805          {4, 0, 5},  // 4
   806          {5, 0, 1}   // 5
   807      };
   808
   809      // get the correct set of substrate vertices for this resolution
   810      CoordIJK *verts;
   811      if (isResolutionClassIII(*res))
   812          verts = vertsCIII;
   813      else
   814          verts = vertsCII;
   815
   816      // adjust the center point to be in an aperture 33r substrate grid
   817      // these should be composed for speed
   818      _downAp3(&fijk->coord);
   819      _downAp3r(&fijk->coord);
   820
   821      // if res is Class III we need to add a cw aperture 7 to get to
   822      // icosahedral Class II
   823      if (isResolutionClassIII(*res)) {
   824          _downAp7r(&fijk->coord);
   825          *res += 1;
   826      }
   827
   828      // The center point is now in the same substrate grid as the origin
   829      // cell vertices. Add the center point substate coordinates
   830      // to each vertex to translate the vertices to that cell.
   831      for (int v = 0; v < NUM_HEX_VERTS; v++) {
   832          fijkVerts[v].face = fijk->face;
   833          _ijkAdd(&fijk->coord, &verts[v], &fijkVerts[v].coord);
   834          _ijkNormalize(&fijkVerts[v].coord);
   835      }
   836  }
