   838  /**
   839   * Adjusts a FaceIJK address in place so that the resulting cell address is
   840   * relative to the correct icosahedral face.
   841   *
   842   * @param fijk The FaceIJK address of the cell.
   843   * @param res The H3 resolution of the cell.
   844   * @param pentLeading4 Whether or not the cell is a pentagon with a leading
   845   *        digit 4.
   846   * @param substrate Whether or not the cell is in a substrate grid.
   847   * @return 0 if on original face (no overage); 1 if on face edge (only occurs
   848   *         on substrate grids); 2 if overage on new face interior
   849   */
   850  Overage _adjustOverageClassII(FaceIJK *fijk, int res, int pentLeading4,
   851                                int substrate) {
   852      Overage overage = NO_OVERAGE;
   853
   854      CoordIJK *ijk = &fijk->coord;
   855
   856      // get the maximum dimension value; scale if a substrate grid
   857      int maxDim = maxDimByCIIres[res];
   858      if (substrate) maxDim *= 3;
   859
   860      // check for overage
   861      if (substrate && ijk->i + ijk->j + ijk->k == maxDim)  // on edge
   862          overage = FACE_EDGE;
   863      else if (ijk->i + ijk->j + ijk->k > maxDim)  // overage
   864      {
   865          overage = NEW_FACE;
   866
   867          const FaceOrientIJK *fijkOrient;
   868          if (ijk->k > 0) {
   869              if (ijk->j > 0)  // jk "quadrant"
   870                  fijkOrient = &faceNeighbors[fijk->face][JK];
   871              else  // ik "quadrant"
   872              {
   873                  fijkOrient = &faceNeighbors[fijk->face][KI];
   874
   875                  // adjust for the pentagonal missing sequence
   876                  if (pentLeading4) {
   877                      // translate origin to center of pentagon
   878                      CoordIJK origin;
   879                      _setIJK(&origin, maxDim, 0, 0);
   880                      CoordIJK tmp;
   881                      _ijkSub(ijk, &origin, &tmp);
   882                      // rotate to adjust for the missing sequence
   883                      _ijkRotate60cw(&tmp);
   884                      // translate the origin back to the center of the triangle
   885                      _ijkAdd(&tmp, &origin, ijk);
   886                  }
   887              }
   888          } else  // ij "quadrant"
   889              fijkOrient = &faceNeighbors[fijk->face][IJ];
   890
   891          fijk->face = fijkOrient->face;
   892
   893          // rotate and translate for adjacent face
   894          for (int i = 0; i < fijkOrient->ccwRot60; i++) _ijkRotate60ccw(ijk);
   895
   896          CoordIJK transVec = fijkOrient->translate;
   897          int unitScale = unitScaleByCIIres[res];
   898          if (substrate) unitScale *= 3;
   899          _ijkScale(&transVec, unitScale);
   900          _ijkAdd(ijk, &transVec, ijk);
   901          _ijkNormalize(ijk);
   902
   903          // overage points on pentagon boundaries can end up on edges
   904          if (substrate && ijk->i + ijk->j + ijk->k == maxDim)  // on edge
   905              overage = FACE_EDGE;
   906      }
   907
   908      return overage;
   909  }
