   911  /**
   912   * Adjusts a FaceIJK address for a pentagon vertex in a substrate grid in
   913   * place so that the resulting cell address is relative to the correct
   914   * icosahedral face.
   915   *
   916   * @param fijk The FaceIJK address of the cell.
   917   * @param res The H3 resolution of the cell.
   918   */
   919  Overage _adjustPentVertOverage(FaceIJK *fijk, int res) {
   920      int pentLeading4 = 0;
   921      Overage overage;
   922      do {
   923          overage = _adjustOverageClassII(fijk, res, pentLeading4, 1);
   924      } while (overage == NEW_FACE);
   925      return overage;
   926  }
