   928  /**
   929   * Encodes a coordinate on the sphere to the corresponding icosahedral face and
   930   * containing the squared euclidean distance to that face center.
   931   *
   932   * @param g The spherical coordinates to encode.
   933   * @param face The icosahedral face containing the spherical coordinates.
   934   * @param sqd The squared euclidean distance to its icosahedral face center.
   935   */
   936  void _geoToClosestFace(const LatLng *g, int *face, double *sqd) {
   937      Vec3d v3d;
   938      _geoToVec3d(g, &v3d);
   939
   940      // determine the icosahedron face
   941      *face = 0;
   942      // The distance between two farthest points is 2.0, therefore the square of
   943      // the distance between two points should always be less or equal than 4.0 .
   944      *sqd = 5.0;
   945      for (int f = 0; f < NUM_ICOSA_FACES; ++f) {
   946          double sqdT = _pointSquareDist(&faceCenterPoint[f], &v3d);
   947          if (sqdT < *sqd) {
   948              *face = f;
   949              *sqd = sqdT;
   950          }
   951      }
   952  }
